// Base64-encode the downloaded binary for AURON's vision endpoint.
// AURON never holds a Drive credential itself -- n8n fetches bytes,
// AURON only ever sees the encoded image it's handed.
const binary = $input.item.binary.data;
const base64 = binary.data;
const mediaType = binary.mimeType || 'image/jpeg';
const isVideo = mediaType.startsWith('video/');

// Reads the real duration out of the video's own MP4 'mvhd' atom
// (duration / timescale) by walking the box structure directly on the
// raw bytes -- no ffmpeg/ffprobe binary required, which the stock n8n
// image does not ship with. Returns null (never a guess) if the file
// isn't a box-structured container this can parse (e.g. some legacy
// avi/mov variants) -- AURON's own analyze-and-ingest endpoint already
// rejects a video item with duration_seconds=null with a clear error
// rather than silently accepting a wrong or missing duration.
function readMp4DurationSeconds(buffer) {
  function walk(buf, start, end) {
    let pos = start;
    while (pos + 8 <= end) {
      let size = buf.readUInt32BE(pos);
      const type = buf.toString('ascii', pos + 4, pos + 8);
      let headerSize = 8;
      if (size === 1) {
        if (pos + 16 > end) break;
        const high = buf.readUInt32BE(pos + 8);
        const low = buf.readUInt32BE(pos + 12);
        size = high * 2 ** 32 + low;
        headerSize = 16;
      } else if (size === 0) {
        size = end - pos;
      }
      if (size < headerSize || pos + size > end) break;

      if (type === 'moov') {
        const result = walk(buf, pos + headerSize, pos + size);
        if (result !== null) return result;
      } else if (type === 'mvhd') {
        const body = pos + headerSize;
        const version = buf.readUInt8(body);
        if (version === 1) {
          const timescale = buf.readUInt32BE(body + 20);
          const durHigh = buf.readUInt32BE(body + 24);
          const durLow = buf.readUInt32BE(body + 28);
          if (timescale > 0) return (durHigh * 2 ** 32 + durLow) / timescale;
        } else {
          const timescale = buf.readUInt32BE(body + 12);
          const duration = buf.readUInt32BE(body + 16);
          if (timescale > 0) return duration / timescale;
        }
      }
      pos += size;
    }
    return null;
  }

  try {
    return walk(buffer, 0, buffer.length);
  } catch {
    return null;
  }
}

let durationSeconds = null;
if (isVideo) {
  durationSeconds = readMp4DurationSeconds(Buffer.from(base64, 'base64'));
}

return {
  json: {
    media_ref: $input.item.json.id,
    media_type: isVideo ? 'video' : 'image',
    image_base64: isVideo ? null : base64,
    image_media_type: isVideo ? null : mediaType,
    duration_seconds: durationSeconds
  }
};
